lookup.day_rate:
// Labour Protection Act B.E. 2541 s.68: the monthly wage over 30 days, fixed allowance included (s.5).
// Proration: no section sets an incomplete month. s.56(1) pays a monthly wage through weekly holidays
// and s.68 counts the month in days, so a salary follows calendar days.
const terms = ctx.subject.employment.terms;
const unit = get(terms, 'rate.unit', 'MONTHLY');
const amount = Number(get(terms, 'rate.amount', 0));
const hours = Number(
	get(
		terms,
		'normal_hours_per_day',
		get(terms, 'statutory_work_category', '') === 'HAZARDOUS'
			? ctx.lookup.hazardous_normal_hours_per_day
			: ctx.lookup.normal_hours_per_day
	)
);
if (unit === 'DAILY') return amount;
if (unit === 'HOURLY' || unit === 'PIECE') return amount * hours;
return (amount + Number(get(terms, 'allowances.FIXED_ALLOWANCE.amount', 0))) / ctx.lookup.monthly_divisor;
